            facade["threadInvites"] = bindTableFacade(db, "threadInvites");
            facade["threadKnowledge"] = bindTableFacade(db, "threadKnowledge");
            facade["threadPins"] = bindTableFacade(db, "threadPins");
            facade["threadRelationships"] = bindTableFacade(db, "threadRelationships");
            facade["threads"] = bindTableFacade(db, "threads");
            facade["threadTags"] = bindTableFacade(db, "threadTags");
            facade["threadVariables"] = bindTableFacade(db, "threadVariables");
